{
  "id": "SPEC-WS-GATEWAY-v1",
  "name": "WebSocket Gateway & IPC Stream Protocol Specification",
  "version": "1.0.0",
  "status": "APPROVED",
  "lastUpdated": "2026-08-23T20:50:00Z",
  "description": "Full-duplex WebSocket protocol specification for real-time IPC task queueing, desktop perception ingress, Gatekeeper escalation resolution, and autonomic Concierge HUD/Avatar event streams.",
  "endpoints": [
    "/v1/ws",
    "/v1/concierge/stream"
  ],
  "authentication": {
    "type": "CHARON_API_KEY",
    "mechanisms": [
      {
        "location": "Header",
        "key": "X-API-Key"
      },
      {
        "location": "Header",
        "key": "Authorization",
        "format": "Bearer <CHARON_API_KEY>"
      },
      {
        "location": "QueryParameter",
        "key": "api_key"
      }
    ],
    "unauthorizedCloseCode": 1008
  },
  "protocol": {
    "transport": "WebSocket",
    "format": "JSON",
    "encoding": "UTF-8"
  },
  "channels": {
    "inboundActions": [
      {
        "action": "ping",
        "aliases": ["heartbeat"],
        "description": "Client heartbeat check to verify connection status and latency.",
        "payload": {},
        "responseEvent": {
          "event_type": "status_change",
          "data": {
            "status": "alive",
            "client_id": "string",
            "timestamp": "ISO-8601 UTC string"
          }
        }
      },
      {
        "action": "submit_task",
        "description": "Enqueues an execution task into the daemon Task Journal.",
        "payload": {
          "prompt": "string (required)",
          "client_id": "string (optional)",
          "agent_override": "string (optional)",
          "context": "object (optional)"
        },
        "responseEvent": {
          "event_type": "status_change",
          "task_id": "string",
          "data": {
            "status": "queued",
            "task_id": "string"
          }
        }
      },
      {
        "action": "gatekeeper_respond",
        "aliases": ["approval_response"],
        "description": "Resolves a paused Gatekeeper Level 2/3 escalation intercept.",
        "payload": {
          "approval_id": "string (required)",
          "decision": "string (required: 'APPROVED' | 'REJECTED')"
        },
        "responseEvent": null
      },
      {
        "action": "concierge_interact",
        "aliases": ["user_message"],
        "description": "Dispatches a natural language prompt directly to the resident Concierge Service.",
        "payload": {
          "prompt": "string (required, alternative key: 'text')",
          "target_app": "string (optional, default: 'Desktop')"
        },
        "responseEvent": {
          "schema": "ConciergeStreamEvent",
          "type": "interact_response"
        }
      },
      {
        "action": "push_context",
        "description": "Ingests active desktop window focus or IDE buffer context into sensory perception sensors.",
        "payload": {
          "context_type": "string (required: 'window' | 'ide')",
          "payload": {
            "app_name": "string",
            "window_title": "string",
            "active_file_path": "string | null",
            "pid": "integer | null",
            "editor": "string (e.g., 'VSCode')",
            "language": "string",
            "selection_or_diff": "string | null",
            "diagnostics": "array of objects | null"
          }
        },
        "responseEvent": null
      },
      {
        "action": "cursor_motion",
        "description": "Ingests desktop shell cursor motion coordinates for context awareness.",
        "payload": {
          "x": "number (float, required)",
          "y": "number (float, required)",
          "active_element": "string | null"
        },
        "responseEvent": null
      },
      {
        "action": "pointer_telemetry",
        "description": "Peer-to-peer desktop shell pointer telemetry broadcast.",
        "payload": "object",
        "responseEvent": "Broadcasted raw to all connected sockets except sender"
      }
    ],
    "outboundEventSchemas": {
      "ConciergeStreamEvent": {
        "description": "Multi-modal event payload for real-time desktop overlays, avatar animations, and speech lip-syncing.",
        "schema": {
          "event_id": "string (format: 'evt_' + 12 hex chars)",
          "timestamp": "ISO-8601 UTC string",
          "type": "string (enum: 'proactive_interjection', 'avatar_state_update', 'diagnostic_alert', 'cursor_motion', 'interact_response')",
          "payload": {
            "text": "string",
            "suggested_action": "string | null",
            "avatar_state": {
              "emotion": "string (e.g., 'attentive', 'speaking')",
              "viseme_sequence": "array of viseme mouth shapes"
            },
            "hud_overlay": {
              "target_app": "string | null",
              "urgency": "string (enum: 'low', 'medium', 'high', 'critical')",
              "pointer_target": {
                "x": "number (float)",
                "y": "number (float)"
              }
            }
          }
        }
      },
      "WSEvent": {
        "description": "Standard system status, task lifecycle, and router telemetry frame.",
        "schema": {
          "event_type": "string (e.g., 'status_change', 'router_agent_updated', 'router_tool_toggled')",
          "task_id": "string | null",
          "agent_name": "string",
          "client_id": "string | null",
          "data": "object"
        }
      }
    }
  }
}
